import{_ as n,o as i,c as e,a5 as h}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"AI Iteration 1 — Individual Report","description":"","frontmatter":{},"headers":[],"relativePath":"plan/iterations/iteration_1/members/locnt.md","filePath":"plan/iterations/iteration_1/members/locnt.md"}'),a={name:"plan/iterations/iteration_1/members/locnt.md"};function o(c,t,r,d,l,s){return i(),e("div",null,[...t[0]||(t[0]=[h('<h1 id="ai-iteration-1-—-individual-report" tabindex="-1">AI Iteration 1 — Individual Report <a class="header-anchor" href="#ai-iteration-1-—-individual-report" aria-label="Permalink to &quot;AI Iteration 1 — Individual Report&quot;">​</a></h1><hr><h2 id="_1-thong-tin-ca-nhan" tabindex="-1">1. Thông tin cá nhân <a class="header-anchor" href="#_1-thong-tin-ca-nhan" aria-label="Permalink to &quot;1. Thông tin cá nhân&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Họ tên</td><td>Nguyễn Thành Lộc</td></tr><tr><td>GitHub</td><td>[@locnt]</td></tr><tr><td>Role</td><td>Frontend / AI Infra</td></tr><tr><td>Iteration</td><td>Iteration 1 — Research &amp; Evaluation</td></tr><tr><td>Ngày nộp</td><td>13/07/2026</td></tr></tbody></table><hr><h2 id="_2-tasks-đuoc-giao-trong-iteration-nay" tabindex="-1">2. Tasks được giao trong iteration này <a class="header-anchor" href="#_2-tasks-đuoc-giao-trong-iteration-nay" aria-label="Permalink to &quot;2. Tasks được giao trong iteration này&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Jira Link</th><th>Mô tả</th><th>Priority</th><th>Status cuối iteration</th></tr></thead><tbody><tr><td>DA-AI01-05</td><td><a href="https://letritrung2605.atlassian.net/browse/DA-AI01-05" target="_blank" rel="noreferrer">DA-AI01-05</a></td><td>Research product + model image compositing techniques</td><td>🟡 High</td><td>🟢 Done</td></tr><tr><td>DA-AI01-06</td><td><a href="https://letritrung2605.atlassian.net/browse/DA-AI01-06" target="_blank" rel="noreferrer">DA-AI01-06</a></td><td>Test 3 compositing methods on 10 product + model image pairs</td><td>🟡 High</td><td>🟢 Done</td></tr><tr><td>DA-AI02-01</td><td><a href="https://letritrung2605.atlassian.net/browse/DA-AI02-01" target="_blank" rel="noreferrer">DA-AI02-01</a></td><td>Initialize brandhub-ai-service project: FastAPI + Python 3.13 + folder structure</td><td>🔴 Critical</td><td>🟢 Done</td></tr><tr><td>DA-AI02-03</td><td><a href="https://letritrung2605.atlassian.net/browse/DA-AI02-03" target="_blank" rel="noreferrer">DA-AI02-03</a></td><td>Configure AWS S3 client with boto3, write helper functions</td><td>🔴 Critical</td><td>🟢 Done</td></tr><tr><td>DA-AI02-05</td><td><a href="https://letritrung2605.atlassian.net/browse/DA-AI02-05" target="_blank" rel="noreferrer">DA-AI02-05</a></td><td>Write Dockerfile for ai-service + add to docker-compose.yml</td><td>🔴 Critical</td><td>🟢 Done</td></tr></tbody></table><p><strong>Tổng:</strong> 5 tasks | Done: 5 | In Review: 0 | Chưa hoàn thành: 0</p><hr><h2 id="_3-chi-tiet-cong-viec-đa-lam" tabindex="-1">3. Chi tiết công việc đã làm <a class="header-anchor" href="#_3-chi-tiet-cong-viec-đa-lam" aria-label="Permalink to &quot;3. Chi tiết công việc đã làm&quot;">​</a></h2><h3 id="_1-da-ai01-05-—-nghien-cuu-cac-ky-thuat-ghep-anh-san-pham-model" tabindex="-1">1. DA-AI01-05 — Nghiên cứu các kỹ thuật ghép ảnh sản phẩm + model <a class="header-anchor" href="#_1-da-ai01-05-—-nghien-cuu-cac-ky-thuat-ghep-anh-san-pham-model" aria-label="Permalink to &quot;1. DA-AI01-05 — Nghiên cứu các kỹ thuật ghép ảnh sản phẩm + model&quot;">​</a></h3><ul><li><strong>Nội dung nghiên cứu:</strong> Tập trung nghiên cứu phương pháp ghép vật phẩm/sản phẩm vào bối cảnh người mẫu (Product In-Context / Model Compositing) bằng các kỹ thuật sinh ảnh khuếch tán tiên tiến kết hợp xử lý đồ họa truyền thống, trọng tâm là mô hình <strong>black-forest-labs/FLUX.1-schnell</strong>: <ol><li><strong>FLUX.1-schnell (Black Forest Labs):</strong> Nghiên cứu tích hợp mô hình text-to-image/image-to-image thế hệ mới sử dụng cấu trúc Flow Matching Transformer. Sử dụng FLUX.1-schnell Inpainting (hoặc các adapter như Flux Fill) để tự động hòa trộn vật phẩm thô vào tay hoặc cơ thể người mẫu. <ul><li><em>Ưu điểm:</em> Khả năng bám sát prompt và hiểu cấu trúc không gian cực tốt; tốc độ sinh ảnh siêu nhanh (chỉ cần 4 steps nhờ cơ chế Latent Adversarial Diffusion Distillation); chất lượng ánh sáng, chi tiết da người, nếp gấp trang phục và bóng đổ xung quanh vật phẩm đạt mức độ tự nhiên vượt trội so với dòng SDXL cũ.</li><li><em>Nhược điểm:</em> Dung lượng mô hình rất nặng (yêu cầu cấu hình phần cứng VRAM lớn, chạy tối ưu từ 12GB+ FP8/NF4 trở lên); nếu không bảo vệ vùng mặt nạ (mask) và căn chỉnh denoising strength chuẩn xác thì mô hình dễ làm biến dạng logo hoặc thay đổi kiểu dáng chi tiết của sản phẩm.</li></ul></li><li><strong>ControlNet Inpainting &amp; DALL-E Edit API:</strong> Nghiên cứu làm phương án so sánh đối chiếu. DALL-E 3 Edit cho chất lượng tốt nhưng chi phí API cao ($0.02 - $0.08/ảnh) và phụ thuộc internet; ControlNet SDXL cần nhiều bước lặp hơn (20-30 steps) nên chậm hơn đáng kể so với FLUX.1-schnell.</li><li><strong>Rembg + Pillow Composite (Xếp lớp đồ họa):</strong> Tách nền vật phẩm dán đè lên mẫu bằng Pillow. Giữ nguyên 100% thương hiệu sản phẩm nhưng biên ghép thô và hoàn toàn không tự động sinh được bóng tiếp xúc (contact shadows).</li></ol></li><li><strong>Kết quả &amp; Đề xuất:</strong> Đề xuất kiến trúc lai: Sử dụng <strong>Rembg + Pillow</strong> để định vị vật phẩm chính xác lên mẫu, sau đó khoét mask vùng tiếp giáp (bàn tay cầm, chân tiếp xúc bệ) và đưa qua <strong>FLUX.1-schnell Inpainting (Denoising thấp ~0.3 - 0.4)</strong> để sinh ánh sáng và bóng đổ hòa trộn biên mà không làm hỏng chi tiết lõi của sản phẩm.</li></ul><h3 id="_2-da-ai01-06-—-thu-nghiem-3-phuong-phap-ghep-anh-tren-10-cap-anh-san-pham-mau" tabindex="-1">2. DA-AI01-06 — Thử nghiệm 3 phương pháp ghép ảnh trên 10 cặp ảnh sản phẩm + mẫu <a class="header-anchor" href="#_2-da-ai01-06-—-thu-nghiem-3-phuong-phap-ghep-anh-tren-10-cap-anh-san-pham-mau" aria-label="Permalink to &quot;2. DA-AI01-06 — Thử nghiệm 3 phương pháp ghép ảnh trên 10 cặp ảnh sản phẩm + mẫu&quot;">​</a></h3><ul><li><strong>Quá trình thực hiện:</strong> Tiến hành ghép thử nghiệm 10 vật phẩm (như túi xách thời trang, bình giữ nhiệt, mỹ phẩm dạng chai thủy tinh) lên các hình ảnh tư thế người mẫu khác nhau. Thử nghiệm inpainting với <strong>FLUX.1-schnell</strong> thông qua cloud API (Fal.ai / Replicate) và so sánh chất lượng với SDXL và Pillow thuần túy.</li><li><strong>Kết quả đánh giá (Rubric điểm 1-5):</strong><ul><li><em>FLUX.1-schnell Inpainting:</em> Điểm biên hòa trộn (4.7), Điểm bóng tiếp xúc (4.6), Ánh sáng nhất quán (4.7), Thời gian (1.8s), Chi phí (~$0.003 trên serverless GPU).</li><li><em>Rembg + Pillow thuần:</em> Điểm biên (3.5), Điểm bóng (2.5), Ánh sáng (3.0), Thời gian (1.2s), Chi phí ($0).</li><li><em>ControlNet SDXL Inpainting:</em> Điểm biên (4.2), Điểm bóng (4.0), Ánh sáng (4.1), Thời gian (4.8s trên GPU T4), Chi phí (~$0.015).</li></ul></li><li><strong>Kết luận từ thử nghiệm:</strong> FLUX.1-schnell vượt trội hoàn toàn về mặt thẩm mỹ nghệ thuật quảng cáo. Tuy nhiên, đối với các sản phẩm có chữ/logo nhỏ, inpainting vẫn có tỉ lệ làm biến dạng chữ nhẹ (đạt 2/10 case bị méo logo nhẹ ở denoising strength &gt; 0.45). Do đó, giải pháp tối ưu là giữ mask vùng logo cố định và chỉ inpaint vùng biên xung quanh vật phẩm tiếp xúc với người mẫu.</li></ul><h3 id="_3-da-ai02-01-—-khoi-tao-du-an-brandhub-ai-service-fastapi-python-3-13" tabindex="-1">3. DA-AI02-01 — Khởi tạo dự án brandhub-ai-service (FastAPI + Python 3.13) <a class="header-anchor" href="#_3-da-ai02-01-—-khoi-tao-du-an-brandhub-ai-service-fastapi-python-3-13" aria-label="Permalink to &quot;3. DA-AI02-01 — Khởi tạo dự án brandhub-ai-service (FastAPI + Python 3.13)&quot;">​</a></h3><ul><li><strong>Công việc thực hiện:</strong><ul><li>Khởi tạo khung dự án sử dụng FastAPI và quản lý dependency bằng <code>requirements.txt</code>.</li><li>Cấu trúc thư mục chuẩn hóa giúp phát triển song song dễ dàng: <ul><li><code>app/api/v1/endpoints/</code>: Định nghĩa các router cho từng feature (<code>content.py</code>, <code>image.py</code>, <code>video.py</code>, <code>ambassador.py</code>, <code>compose.py</code>, <code>rag.py</code>, <code>trends.py</code>).</li><li><code>app/core/</code>: Quản lý file cấu hình <code>config.py</code> (sử dụng <code>pydantic-settings</code> để đọc từ <code>.env</code>) và bảo mật <code>security.py</code> (chứa dependency <code>verify_internal_key</code>).</li><li><code>app/services/</code>: Nơi chứa logic nghiệp vụ chính.</li><li><code>app/utils/</code>: Các cấu hình dùng chung như kết nối S3.</li><li><code>tests/</code>: Nơi viết unit test cho hệ thống.</li></ul></li><li>Setup thành công endpoint <code>GET /health</code> trả về <code>{&quot;status&quot;: &quot;ok&quot;}</code> khi khởi động qua uvicorn trên cổng 8082.</li></ul></li></ul><h3 id="_4-da-ai02-03-—-cau-hinh-aws-s3-client-voi-boto3-viet-cac-helper-functions" tabindex="-1">4. DA-AI02-03 — Cấu hình AWS S3 client với boto3 &amp; viết các helper functions <a class="header-anchor" href="#_4-da-ai02-03-—-cau-hinh-aws-s3-client-voi-boto3-viet-cac-helper-functions" aria-label="Permalink to &quot;4. DA-AI02-03 — Cấu hình AWS S3 client với boto3 &amp; viết các helper functions&quot;">​</a></h3><ul><li><strong>Công việc thực hiện:</strong><ul><li>Viết file <code>app/utils/s3.py</code> triển khai client kết nối S3 thông qua thư viện <code>boto3</code>, lấy credentials từ biến môi trường.</li><li>Triển khai 3 hàm helper chính: <ul><li><code>upload_file(local_path, s3_key)</code>: Hỗ trợ truyền cả đường dẫn file cục bộ hoặc dữ liệu dạng <code>bytes</code> trong bộ nhớ (hữu ích cho việc upload trực tiếp ảnh vừa sinh từ AI). Tự động xác định MIME type chính xác (<code>image/png</code>, <code>video/mp4</code>) để trình duyệt hiển thị đúng.</li><li><code>get_presigned_url(s3_key, expires_in)</code>: Sinh URL tạm thời có thời hạn truy cập an toàn.</li><li><code>delete_file(s3_key)</code>: Xóa tệp tin trên S3.</li></ul></li><li>Viết bộ unit tests đầy đủ tại <code>tests/test_s3.py</code> sử dụng thư viện mock <code>moto</code> để chạy test độc lập trong môi trường CI/CD mà không cần AWS credentials thật.</li></ul></li></ul><h3 id="_5-da-ai02-05-—-viet-dockerfile-cho-ai-service-va-tich-hop-vao-docker-compose-yml" tabindex="-1">5. DA-AI02-05 — Viết Dockerfile cho ai-service và tích hợp vào docker-compose.yml <a class="header-anchor" href="#_5-da-ai02-05-—-viet-dockerfile-cho-ai-service-va-tich-hop-vao-docker-compose-yml" aria-label="Permalink to &quot;5. DA-AI02-05 — Viết Dockerfile cho ai-service và tích hợp vào docker-compose.yml&quot;">​</a></h3><ul><li><strong>Công việc thực hiện:</strong><ul><li>Viết <code>Dockerfile</code> tối ưu sử dụng cơ chế multi-stage build để giảm dung lượng file ảnh chạy cuối cùng: <ul><li>Stage <code>builder</code>: Cài đặt build dependencies và cài trước gói <code>torch==2.5.1+cpu</code> từ index URL riêng của PyTorch để tránh cài bản GPU quá nặng, sau đó cài các dependencies trong <code>requirements.txt</code>.</li><li>Stage <code>runner</code>: Sử dụng image base <code>python:3.11-slim</code> siêu nhẹ, copy packages đã build từ stage builder sang, đảm bảo ứng dụng chạy mượt mà và an toàn.</li></ul></li><li>Cập nhật file <code>docker-compose.apps.yml</code> trong repository infrastructure để định nghĩa service <code>ai-service</code> chạy trên port 8082, liên kết network với <code>chromadb</code> và <code>redis</code>, mount config qua file <code>.env</code>.</li><li>Kiểm thử khởi động service thông qua container docker chạy ổn định, thời gian build lần đầu dưới 3 phút.</li></ul></li></ul><hr><h2 id="_4-tasks-chua-hoan-thanh" tabindex="-1">4. Tasks chưa hoàn thành <a class="header-anchor" href="#_4-tasks-chua-hoan-thanh" aria-label="Permalink to &quot;4. Tasks chưa hoàn thành&quot;">​</a></h2><ul><li>Không có. Hoàn thành 100% các task được giao đúng tiến độ.</li></ul><hr><h2 id="_5-đong-gop-ngoai-tasks-chinh" tabindex="-1">5. Đóng góp ngoài tasks chính <a class="header-anchor" href="#_5-đong-gop-ngoai-tasks-chinh" aria-label="Permalink to &quot;5. Đóng góp ngoài tasks chính&quot;">​</a></h2><ul><li>Hỗ trợ các thành viên khác cấu hình môi trường chạy Docker cục bộ để tích hợp chung các dịch vụ.</li><li>Hỗ trợ cài đặt và debug các thư viện Python, xử lý lỗi cài đặt dependency <code>moto</code> và <code>boto3</code> trên môi trường Windows.</li></ul><hr><h2 id="_6-hoc-đuoc-gi-trong-iteration-nay" tabindex="-1">6. Học được gì trong iteration này <a class="header-anchor" href="#_6-hoc-đuoc-gi-trong-iteration-nay" aria-label="Permalink to &quot;6. Học được gì trong iteration này&quot;">​</a></h2><ul><li>Hiểu sâu về các kỹ thuật xử lý ảnh, tách nền sử dụng mô hình học máy (U2Net, ISNet) và cách ghép ảnh theo tọa độ, quản lý kênh alpha thông qua Pillow trong Python.</li><li>Nâng cao kinh nghiệm thiết kế kiến trúc REST API hướng microservice sử dụng FastAPI.</li><li>Học cách viết unit test mock AWS S3 hiệu quả bằng <code>pytest</code> và <code>moto</code> giúp quá trình phát triển độc lập và an toàn hơn.</li><li>Hiểu rõ cơ chế tối ưu dung lượng image Docker cho ứng dụng Python có sử dụng các thư viện tính toán lớn như PyTorch.</li></ul><hr><h2 id="_7-feedback-đe-xuat" tabindex="-1">7. Feedback &amp; Đề xuất <a class="header-anchor" href="#_7-feedback-đe-xuat" aria-label="Permalink to &quot;7. Feedback &amp; Đề xuất&quot;">​</a></h2><ul><li>Cần thống nhất sớm chuẩn format API giữa Frontend/Backend và AI Service (đã làm trong DA-E07-04) để tránh mất thời gian map data ở các iteration sau.</li><li>Nên xây dựng sớm bộ test dataset chuẩn cho cả 3 nhánh AI (hình ảnh sản phẩm thật, model thật, video mẫu) để quá trình đánh giá chất lượng đầu ra được đồng đều và khách quan hơn.</li></ul><hr><h2 id="_8-self-assessment" tabindex="-1">8. Self-assessment <a class="header-anchor" href="#_8-self-assessment" aria-label="Permalink to &quot;8. Self-assessment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Điểm (1-5)</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Hoàn thành đúng deadline</td><td>5/5</td><td>Hoàn thành toàn bộ 5/5 task đúng hạn</td></tr><tr><td>Chất lượng deliverable</td><td>5/5</td><td>Code được bao phủ bởi unit test đầy đủ, docker chạy ổn định, báo cáo nghiên cứu chi tiết</td></tr><tr><td>Giao tiếp với team</td><td>5/5</td><td>Chủ động thảo luận, thống nhất cấu trúc dự án và hỗ trợ team</td></tr><tr><td>Chủ động xử lý blocker</td><td>5/5</td><td>Chủ động tìm hiểu giải pháp mock S3 và tối ưu build PyTorch CPU</td></tr><tr><td><strong>Tổng</strong></td><td><strong>20/20</strong></td><td></td></tr></tbody></table><hr><p><em>Deadline nộp: cuối Iteration 1 (song song Sprint 5–6)</em></p>',37)])])}const p=n(a,[["render",o]]);export{u as __pageData,p as default};
